// Normaliza os dados recebidos pelo Webhook
const item = $input.first().json.body || $input.first().json;
return [{
  json: {
    solicitacaoOriginal: item.mensagem || item.texto || item.solicitacao || 'Solicitação comercial não especificada',
    cliente: item.cliente || item.remetente || 'Lead WhatsApp / Instagram',
    canalOrigem: item.canal || 'WhatsApp',
    prazoUrgencia: item.prazo || item.urgencia || null,
    recebido_em: new Date().toISOString()
  }
}];

const dados = $input.first().json;
return [{
  json: {
    status: 'PROJETO AUTORIZADO EM EXECUÇÃO',
    id_projeto: dados.resultado.etapa_02_coordenador.id_projeto,
    id_demanda: dados.resultado.etapa_01_triagem.idDemanda,
    cliente: dados.resultado.etapa_02_coordenador.cliente,
    tarefas_ativas: dados.resultado.etapa_02_coordenador.grafo_tarefas.length,
    mensagem: `O Coordenador Geral ativou o grafo operacional com ${dados.resultado.etapa_02_coordenador.grafo_tarefas.length} tarefas.`
  }
}];

